import fs from 'node:fs';import path from 'node:path';import cp from 'node:child_process';import crypto from 'node:crypto';import os from 'node:os';import assert from 'node:assert/strict';import {fileURLToPath,pathToFileURL} from 'node:url';import {finished} from 'node:stream/promises';

export function createLifecycleMirror(trace,{writeLine=line=>process.stdout.write(line),intervalMs=2000}={}){
 assert.ok(path.isAbsolute(trace)&&path.basename(trace)==='lifecycle.original.jsonl'&&path.basename(path.dirname(trace))==='unit4-probe'&&path.basename(path.dirname(path.dirname(trace)))==='.vercel');assert.ok(typeof writeLine==='function'&&Number.isSafeInteger(intervalMs)&&intervalMs>=10&&intervalMs<=2000);
 let offset=0,lineCount=0,flushCount=0,stopped=false;const errors=[];
 function flush(){
  flushCount++;try{if(!fs.existsSync(trace))return;const bytes=fs.readFileSync(trace);assert.ok(bytes.length>=offset,'Lifecycle trace was truncated');let next;
   while((next=bytes.indexOf(10,offset))!==-1){const line=bytes.subarray(offset,next).toString('utf8');writeLine('UNIT4-LIFECYCLE '+line+'\n');offset=next+1;lineCount++;}
  }catch(error){const value={code:error.code??null,message:error.message};errors.push(value);try{writeLine('UNIT4-LIFECYCLE-ERROR '+JSON.stringify(value)+'\n')}catch{}}
 }
 const timer=setInterval(flush,intervalMs);
 const state=()=>({intervalMs,offsetBytes:offset,lineCount,flushCount,errors:[...errors],stopped});
 return{flush,stop(){if(!stopped){clearInterval(timer);flush();stopped=true}return state()},state};
}

async function unit4ProbeMain(){
const [mode,sourceArgument,assetsArgument,concurrency]=process.argv.slice(2);assert.ok(['prepare','run','finalize'].includes(mode));assert.ok(path.isAbsolute(sourceArgument)&&path.isAbsolute(assetsArgument));const root=path.resolve(sourceArgument),assets=path.resolve(assetsArgument),directory=path.join(root,'.vercel/unit4-probe'),sha=b=>crypto.createHash('sha256').update(b).digest('hex'),json=p=>JSON.parse(fs.readFileSync(p,'utf8')),binding=json(path.join(assets,'.github/probes/unit4-source-bindings.json')),git=(cwd,...args)=>cp.execFileSync('git',args,{cwd,encoding:'utf8',maxBuffer:30*1024*1024}),write=(name,value)=>fs.writeFileSync(path.join(directory,name),JSON.stringify(value,null,2)+'\n',{flag:'wx'});
assert.equal(binding.state,'SEALED_UNIT4_DIAGNOSTIC_SOURCE');assert.match(binding.sourceSha,/^[a-f0-9]{40}$/);assert.equal(binding.productionTests,348);assert.equal(binding.selected.length,22);assert.equal(binding.shard,4);assert.equal(binding.shardCount,16);assert.equal(sha(fs.readFileSync(path.join(assets,'.github/scripts/unit4-probe-observer.mjs'))),binding.observerSha256);assert.equal(sha(fs.readFileSync(fileURLToPath(import.meta.url))),binding.runnerSha256);
function sourceSnapshot(){assert.equal(git(root,'rev-parse','HEAD').trim(),binding.sourceSha);assert.equal(git(root,'rev-parse','HEAD^{tree}').trim(),binding.sourceTree);assert.equal(git(root,'status','--porcelain'),'');const paths=git(root,'ls-files','-z').split('\0').filter(Boolean).sort();assert.deepEqual(paths,binding.sources.map(r=>r.path));const sources=paths.map(file=>{const p=path.join(root,file);assert.ok(fs.lstatSync(p).isFile()&&!fs.lstatSync(p).isSymbolicLink());const bytes=fs.readFileSync(p);return{path:file,bytes:bytes.length,sha256:sha(bytes)}});assert.deepEqual(sources,binding.sources);const universe=paths.filter(p=>/^tests\/production-.*\.test\.mjs$/.test(p));assert.equal(universe.length,348);assert.equal(sha(JSON.stringify(universe)),binding.universePathsSha256);assert.deepEqual(universe.filter((_,i)=>i%16===3),binding.selected);return{head:binding.sourceSha,tree:binding.sourceTree,trackedClean:true,sources,universeCount:348,universePathsSha256:binding.universePathsSha256,selected:[...binding.selected]}}
function opsSnapshot(){const head=git(assets,'rev-parse','HEAD').trim();assert.equal(head,process.env.GITHUB_SHA,'Ops checkout must keep the real workflow GITHUB_SHA');assert.equal(git(assets,'status','--porcelain'),'');return{head,tree:git(assets,'rev-parse','HEAD^{tree}').trim(),trackedClean:true,sources:git(assets,'ls-files','-z').split('\0').filter(Boolean).sort().map(file=>{const b=fs.readFileSync(path.join(assets,file));return{path:file,bytes:b.length,sha256:sha(b)}})}}
if(mode==='prepare'){
 assert.equal(fs.existsSync(directory),false,'Diagnostic output must be fresh');fs.mkdirSync(directory,{recursive:true});for(const p of [path.join(root,'.vercel'),directory])assert.ok(fs.lstatSync(p).isDirectory()&&!fs.lstatSync(p).isSymbolicLink());write('parent-runtime.json',{node:process.version,availableParallelism:os.availableParallelism(),cpuCount:os.cpus().length,platform:process.platform,pid:process.pid,sourceSha:binding.sourceSha,workflowOpsSha:process.env.GITHUB_SHA,declaredSourceCount:binding.sources.length,noGithubShaSubstitution:true});write('source.before.json',sourceSnapshot());write('ops.before.json',opsSnapshot());write('selection.json',{version:1,paths:[...binding.selected]});write('prepared.json',{state:'EXACT_SOURCE_PREPARED_DIAGNOSTIC_ONLY',sourceSha:binding.sourceSha,files:binding.sources.length,universe:348,selected:22,acceptance:false});
}else if(mode==='run'){
 assert.ok(['node-default','explicit-2'].includes(concurrency));assert.deepEqual(sourceSnapshot(),json(path.join(directory,'source.before.json')));assert.deepEqual(opsSnapshot(),json(path.join(directory,'ops.before.json')));assert.deepEqual(json(path.join(directory,'selection.json')),{version:1,paths:binding.selected});const argv=['--import',pathToFileURL(path.join(assets,'.github/scripts/unit4-probe-observer.mjs')).href,'--test','--test-reporter=tap',...(concurrency==='explicit-2'?['--test-concurrency=2']:[]),...binding.selected];write('execution.started.json',{state:'CHILD_START_REQUESTED',sourceSha:binding.sourceSha,workflowOpsSha:process.env.GITHUB_SHA,concurrency,node:process.version,availableParallelism:os.availableParallelism(),cpuCount:os.cpus().length,argv,selected:22,at:new Date().toISOString()});const stdout=fs.createWriteStream(path.join(directory,'tests.stdout.original.tap'),{flags:'wx'}),stderr=fs.createWriteStream(path.join(directory,'tests.stderr.original.log'),{flags:'wx'}),start=process.hrtime.bigint(),child=cp.spawn(process.execPath,argv,{cwd:root,stdio:['ignore','pipe','pipe']});child.stdout.pipe(stdout);child.stderr.pipe(stderr);child.stdout.on('data',b=>process.stdout.write(b));child.stderr.on('data',b=>process.stderr.write(b));let spawnError=null;child.once('error',error=>{spawnError={code:error.code,message:error.message}});const mirror=createLifecycleMirror(path.join(directory,'lifecycle.original.jsonl'));let finish,mirrorState;try{finish=await new Promise(resolve=>child.once('close',(exitCode,signal)=>resolve({exitCode,signal})));}finally{mirrorState=mirror.stop();write('lifecycle-mirror.result.json',mirrorState)}await Promise.all([finished(stdout),finished(stderr)]);write('execution.result.json',{state:'CHILD_CLOSED_DIAGNOSTIC_ONLY',...finish,spawnError,elapsedMs:Number(process.hrtime.bigint()-start)/1e6,concurrency,sourceSha:binding.sourceSha,acceptance:false});process.exitCode=spawnError||finish.signal||finish.exitCode!==0?1:0;
}else{
 let sources=null,ops=null,fenceError=null,events=[],traceError=null;try{sources=sourceSnapshot();ops=opsSnapshot();assert.deepEqual(sources,json(path.join(directory,'source.before.json')));assert.deepEqual(ops,json(path.join(directory,'ops.before.json')));assert.deepEqual(json(path.join(directory,'selection.json')),{version:1,paths:binding.selected})}catch(error){fenceError={code:error.code??null,message:error.message}}try{const trace=path.join(directory,'lifecycle.original.jsonl');events=fs.existsSync(trace)?fs.readFileSync(trace,'utf8').trim().split('\n').filter(Boolean).map(line=>JSON.parse(line)):[];const groups=new Map();for(const e of events){assert.equal(e.version,1);assert.ok(['START','EXIT'].includes(e.event));assert.ok(binding.selected.includes(e.file));assert.ok(Number.isSafeInteger(e.pid)&&e.pid>0&&Number.isFinite(e.elapsedMs)&&e.elapsedMs>=0);const key=e.file+'#'+e.pid;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(e)}for(const xs of groups.values()){assert.equal(xs[0].event,'START');assert.ok(xs.length===1||xs.length===2&&xs[1].event==='EXIT');assert.ok(xs.every(e=>e.file===xs[0].file&&e.pid===xs[0].pid))}const files=[...new Set(events.filter(e=>e.event==='START').map(e=>e.file))];assert.equal(files.length,groups.size,'One file process per selected file');}catch(error){traceError={code:error.code??null,message:error.message}}if(sources)write('source.after.json',sources);if(ops)write('ops.after.json',ops);const mirrorResult=fs.existsSync(path.join(directory,'lifecycle-mirror.result.json'))?json(path.join(directory,'lifecycle-mirror.result.json')):null;if(mirrorResult?.errors?.length)traceError??={code:'UNIT4_MIRROR_FAILED',message:'The parent lifecycle mirror reported an error'};const starts=events.filter(e=>e.event==='START'),exits=events.filter(e=>e.event==='EXIT'),complete=starts.length===22&&exits.length===22&&exits.every(e=>e.exitCode===0),execution=fs.existsSync(path.join(directory,'execution.result.json'))?json(path.join(directory,'execution.result.json')):null;write('final-fences-and-trace.json',{state:fenceError||traceError?'DIAGNOSTIC_FENCE_OR_TRACE_FAILED':complete&&execution?.exitCode===0?'ALL22_FILE_PROCESSES_COMPLETED_DIAGNOSTIC_ONLY':'PARTIAL_TRACE_DIAGNOSTIC_ONLY',sourceSha:binding.sourceSha,workflowOpsSha:process.env.GITHUB_SHA,sourceRawStable:fenceError===null,opsRawStable:fenceError===null,fenceError,traceError,startCount:starts.length,exitCount:exits.length,unfinished:starts.filter(s=>!exits.some(e=>e.file===s.file&&e.pid===s.pid)).map(e=>({file:e.file,pid:e.pid,startedAt:e.at})),files:binding.selected.map(file=>({file,start:starts.find(e=>e.file===file)||null,exit:exits.find(e=>e.file===file)||null})),execution,mirrorResult,fullTestAcceptance:false,mainCliAcceptance:false,fitUnder45Proven:false});if(fenceError||traceError||execution?.exitCode===0&&!complete)process.exitCode=1;
}

}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url))await unit4ProbeMain();
